gltf={'asset':{'version':'2.0','generator':'RELAY original geometry generator','copyright':'CC0 — RELAY contributors'},'scene':0,'scenes':[{'nodes':[0]}],'nodes':[{'name':'ORA','children':[1,2,3,4,5]},{'name':'shell','mesh':0,'scale':[.38,.22,.28]},{'name':'visor','mesh':1,'translation':[0,0,.285],'scale':[.28,.08,.02]},{'name':'left wing','mesh':0,'translation':[-.58,0,0],'scale':[.25,.035,.16]},{'name':'right wing','mesh':0,'translation':[.58,0,0],'scale':[.25,.035,.16]},{'name':'antenna','mesh':1,'translation':[0,.33,0],'scale':[.035,.13,.035]}],'meshes':[{'primitives':[{'attributes':{'POSITION':0,'NORMAL':1},'indices':2,'material':m}]} for m in range(2)],'materials':[{'name':'ceramic','pbrMetallicRoughness':{'baseColorFactor':[.75,.88,.83,1],'metallicFactor':.3,'roughnessFactor':.25}},{'name':'signal','pbrMetallicRoughness':{'baseColorFactor':[.5,1,.6,1]},'emissiveFactor':[.5,1,.6]}],'animations':[{'name':'Hover','samplers':[{'input':3,'output':4,'interpolation':'LINEAR'}],'channels':[{'sampler':0,'target':{'node':0,'path':'translation'}}]}],'buffers':[{'byteLength':len(blob)}],'bufferViews':views,'accessors':[{'bufferView':0,'componentType':5126,'count':24,'type':'VEC3','min':[-1,-1,-1],'max':[1,1,1]},{'bufferView':1,'componentType':5126,'count':24,'type':'VEC3'},{'bufferView':2,'componentType':5123,'count':36,'type':'SCALAR'},{'bufferView':3,'componentType':5126,'count':3,'type':'SCALAR','min':[0],'max':[2]},{'bufferView':4,'componentType':5126,'count':3,'type':'VEC3'}]}
j=json.dumps(gltf,separators=(',',':')).encode();j+=b' '*((-len(j))%4);blob+=b'\0'*((-len(blob))%4)
data=struct.pack('<III',0x46546c67,2,12+8+len(j)+8+len(blob))+struct.pack('<II',len(j),0x4e4f534a)+j+struct.pack('<II',len(blob),0x004e4942)+blob
path=root/'frontend/public/assets/ora.glb';path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(data)
digest=hashlib.sha256(data).hexdigest()
definition={'type':'model','format':'glb','url':'/assets/ora.glb','hash':'sha256-'+digest,'bounds':[1.66,.7,.6],'sizeBytes':len(data),'metadata':{'animations':['Hover'],'materials':['ceramic','signal'],'license':'CC0-1.0','author':'RELAY contributors','sourcePath':'scripts/generate_drone.py','outputPath':'/assets/ora.glb'}}
(root/'frontend/src/assets.ts').write_text("// Generated by scripts/generate_drone.py; do not edit by hand.\nimport { defineAuraAssets } from '@aura3d/engine';\nexport const assets = defineAuraAssets("+json.dumps({'ora':definition})+" as const);\n",encoding='utf-8')
(root/'frontend/aura.assets.json').write_text(json.dumps({'schema':'relay-asset-provenance/1','assets':{'ora':definition}},indent=2),encoding='utf-8')
